def compute(vars):
    balance_thousand = vars["v1"]
    translation_adjustment_thousand = vars["v2"]
    adjusted_thousand = balance_thousand - translation_adjustment_thousand
    adjusted_million = adjusted_thousand / 1000.0

    return {
        "value": adjusted_million,
        "trace": {
            "balance_thousand": balance_thousand,
            "translation_adjustment_thousand": translation_adjustment_thousand,
            "adjusted_thousand": adjusted_thousand,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
